<?php
declare(strict_types=1);require_once '../config/session.php';require_once '../config/config.php';require_once '../config/functions.php';require_once '../config/auth.php';require_login('student');
$studentId=(int)$_SESSION['user_id'];$examId=filter_input(INPUT_GET,'exam_id',FILTER_VALIDATE_INT);if(!$examId){header('Location: my_exams.php');exit;}
function ed_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
try{$s=$conn->prepare("SELECT e.*,s.name subject_name,s.code subject_code,(SELECT COUNT(DISTINCT eq.question_id) FROM exam_questions eq INNER JOIN questions q ON q.id=eq.question_id WHERE eq.exam_id=e.id AND q.status='Active') active_question_count FROM exams e LEFT JOIN subjects s ON s.id=e.subject_id WHERE e.id=? LIMIT 1");$s->execute([$examId]);$exam=$s->fetch();if(!$exam){header('Location: my_exams.php');exit;}$a=$conn->prepare("SELECT id FROM exam_attempts WHERE student_id=? AND exam_id=? AND status='Started' ORDER BY id DESC LIMIT 1");$a->execute([$studentId,$examId]);$activeAttempt=(int)($a->fetchColumn()?:0);$r=$conn->prepare("SELECT id FROM results WHERE student_id=? AND exam_id=? ORDER BY id DESC LIMIT 1");$r->execute([$studentId,$examId]);$resultId=(int)($r->fetchColumn()?:0);$hasSub=has_active_subscription($conn,$studentId);}catch(Throwable $e){error_log($e->getMessage());exit('Unable to load exam details.');}
$ready=(int)$exam['required_question_count']>0&&(int)$exam['active_question_count']===(int)$exam['required_question_count'];$now=new DateTimeImmutable();$start=!empty($exam['starts_at'])?new DateTimeImmutable($exam['starts_at']):null;$end=!empty($exam['ends_at'])?new DateTimeImmutable($exam['ends_at']):null;$state='Unavailable';if($exam['exam_type']==='Practice'&&$exam['status']==='Active')$state='Available';elseif($exam['exam_type']==='Live'){if($end&&$now>$end)$state='Ended';elseif($start&&$now<$start)$state='Upcoming';elseif($start&&$now>=$start&&(!$end||$now<=$end))$state='Live';elseif(in_array($exam['status'],['Live','Running','Active'],true))$state='Live';}
$requiresSub=$exam['exam_type']==='Live'&&(int)$exam['subscription_required']===1;$canStart=$ready&&(($exam['exam_type']==='Practice'&&$state==='Available')||($exam['exam_type']==='Live'&&$state==='Live'&&(!$requiresSub||$hasSub)));
include 'includes/navbar.php';
?><style>
.ed-page{min-height:calc(100vh - 70px);padding:35px 0 65px;background:linear-gradient(180deg,#FAF8F0,#F5F5DC)}.ed-wrap{width:min(1050px,calc(100% - 30px));margin:auto}.ed-card{background:#fff;border:1px solid #E3DDD2;border-radius:24px;overflow:hidden;box-shadow:0 22px 60px rgba(62,39,35,.08)}.ed-head{padding:30px;background:linear-gradient(135deg,#5D4037,#76564B);color:#fff}.ed-k{font-size:9px;letter-spacing:1.6px;color:#D6C56E;font-weight:900}.ed-head h1{font-size:29px;font-weight:900;margin:8px 0}.ed-head p{font-size:11px;color:#F0E6DF;line-height:1.8;margin:0}.ed-body{padding:24px}.ed-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.ed-stat{padding:14px;border:1px solid #E8E1D7;border-radius:12px;background:#FCFAF5}.ed-stat small{display:block;color:#898077;font-size:7px}.ed-stat strong{display:block;color:#3E2723;font-size:16px;margin-top:4px}.ed-desc{margin-top:18px;padding:17px;border-radius:13px;background:#FAF7F1;color:#6E665E;font-size:10px;line-height:1.8}.ed-action{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:45px;padding:0 18px;border-radius:10px;text-decoration:none;font-size:9px;font-weight:900;margin-top:18px}.ed-start{color:#fff;background:#556B2F}.ed-start:hover{color:#fff;background:#455723}.ed-lock{color:#8A651F;background:#FFF3DB}.ed-ended{color:#756D65;background:#F1ECE7}.ed-note{margin-top:12px;color:#7C746D;font-size:8px}@media(max-width:750px){.ed-grid{grid-template-columns:1fr 1fr}}@media(max-width:480px){.ed-grid{grid-template-columns:1fr}}
</style><main class="ed-page"><div class="ed-wrap"><article class="ed-card"><header class="ed-head"><div class="ed-k"><i class="fa-solid fa-file-lines"></i> EXAM DETAILS</div><h1><?=ed_e($exam['title'])?></h1><p><?=ed_e($exam['description']??'')?></p></header><div class="ed-body"><div class="ed-grid"><div class="ed-stat"><small>Type</small><strong><?=ed_e($exam['exam_type'])?></strong></div><div class="ed-stat"><small>Subject</small><strong><?=ed_e($exam['subject_name']??'—')?></strong></div><div class="ed-stat"><small>Questions</small><strong><?= (int)$exam['required_question_count']?></strong></div><div class="ed-stat"><small>Duration</small><strong><?= (int)$exam['duration_minutes']?> min</strong></div><div class="ed-stat"><small>Total Marks</small><strong><?=ed_e($exam['total_marks'])?></strong></div><div class="ed-stat"><small>Passing Marks</small><strong><?=ed_e($exam['passing_marks'])?></strong></div><div class="ed-stat"><small>Negative Marking</small><strong><?=((int)$exam['negative_marking']===1)?'Enabled':'None'?></strong></div><div class="ed-stat"><small>Status</small><strong><?=ed_e($state)?></strong></div></div><div class="ed-desc"><strong>Access:</strong> <?= $requiresSub?($hasSub?'Active subscription verified.':'An active subscription is required.'):'No subscription required.' ?><br><strong>Question readiness:</strong> <?= $ready?'All required active questions are available.':('Required '.$exam['required_question_count'].' | Active '.$exam['active_question_count']) ?></div><?php if($resultId):?><a class="ed-action ed-start" href="result.php?id=<?=$resultId?>"><i class="fa-solid fa-chart-pie"></i> View Result</a><?php elseif($activeAttempt):?><a class="ed-action ed-start" href="take_exam.php?attempt_id=<?=$activeAttempt?>"><i class="fa-solid fa-play"></i> Resume Exam</a><?php elseif($canStart):?><a class="ed-action ed-start" href="start_exam.php?id=<?=(int)$examId?>"><i class="fa-solid fa-play"></i><?= $exam['exam_type']==='Live'?'Join Live Exam':'Start Practice Exam' ?></a><?php elseif($requiresSub&&!$hasSub):?><a class="ed-action ed-lock" href="subscriptions.php"><i class="fa-solid fa-lock"></i> Subscription Required</a><?php else:?><span class="ed-action ed-ended"><i class="fa-solid fa-circle-xmark"></i><?=ed_e($state==='Upcoming'?'Exam Not Started':($state==='Ended'?'Exam Ended':'Exam Not Ready'))?></span><?php endif;?><div class="ed-note">ExamSphere verifies eligibility and question readiness before an attempt is created.</div></div></article></div></main></body></html>
